import{_ as l,r as a,o as c,c as i,e as t,a as s,s as e}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Введение - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Регистрация страницы настроек","slug":"регистрация-страницы-настроек","link":"#регистрация-страницы-настроек","children":[{"level":3,"title":"Свойства настроек","slug":"своиства-настроек","link":"#своиства-настроек","children":[]}]},{"level":2,"title":"Привязка к классу модели","slug":"привязка-к-классу-модели","link":"#привязка-к-классу-модели","children":[]},{"level":2,"title":"Привязка к классу контроллера","slug":"привязка-к-классу-контроллера","link":"#привязка-к-классу-контроллера","children":[{"level":3,"title":"Определение класса страницы настроек","slug":"определение-класса-страницы-настроек","link":"#определение-класса-страницы-настроек","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/extend/settings/settings.md","filePath":"3.x/ru/extend/settings/settings.md"}'),r={name:"3.x/ru/extend/settings/settings.md"};function u(g,n,d,k,h,m){const o=a("pre-heading"),p=a("post-heading");return c(),i("div",null,[t(o),n[0]||(n[0]=s("h1",null,"Введение",-1)),t(p),n[1]||(n[1]=e(`<p>Существует два основных способа настройки системы плагинами. Рекомендуется сначала определить, какой вариант лучше подходит для ваших требований.</p><ul><li><a href="./file-settings.html">Файловая конфигурация</a> без пользовательского интерфейса, хранящаяся в файловой системе.</li><li><a href="./model-settings.html">Настройки на основе модели</a> с необязательным пользовательским интерфейсом, хранящиеся в базе данных.</li></ul><p>Использование настроек на основе модели со страницами панели управления обеспечивает лучший пользовательский опыт, но требует больших затрат на начальную разработку. Файловая конфигурация подходит для конфигурации, которая редко изменяется и не имеет интерфейса, например для настройки политик.</p><h2 id="регистрация-страницы-настроек"><a href="#регистрация-страницы-настроек" class="header-anchor">#</a> Регистрация страницы настроек</h2><p>При использовании настроек на основе модели вы можете опционально зарегистрировать их в специальной области для управления настройками и конфигурацией, доступной по нажатию ссылки <strong>Настройки</strong> в главном меню.</p><p>Страницы настроек должны быть зарегистрированы путём переопределения метода <code>registerSettings</code> в <a href="./../extending.html">файле регистрации плагина</a>. Метод возвращает массив с ключом для каждого элемента настроек и значением, настраивающим модель или контроллер настроек для отображения в области настроек. Ниже приведён пример регистрации модели настроек.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User Settings&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage user based settings.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CATEGORY_USERS&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="своиства-настроек"><a href="#своиства-настроек" class="header-anchor">#</a> Свойства настроек</h3><p>Следующие свойства доступны для каждого ключа при регистрации настроек.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>указывает ключ строки локализации метки меню, обязательно.</td></tr><tr><td><strong>category</strong></td><td>указывает ключ строки локализации метки категории для группировки страниц настроек, обязательно.</td></tr><tr><td><strong>keywords</strong></td><td>указывает ключевые слова, используемые для поиска настроек.</td></tr><tr><td><strong>order</strong></td><td>числовой вес при определении порядка отображения.</td></tr><tr><td><strong>icon</strong></td><td>имя иконки из <a href="./../../element/available-icons.html">коллекции иконок October CMS</a>, необязательно.</td></tr><tr><td><strong>iconSvg</strong></td><td>SVG-иконка для использования вместо стандартной иконки, SVG-иконка должна быть прямоугольной и может поддерживать цвета, необязательно.</td></tr><tr><td><strong>url</strong></td><td>URL панели управления, на который должен ссылаться элемент меню, например <code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>.</td></tr><tr><td><strong>class</strong></td><td>класс модели, на который должен ссылаться элемент настроек, например <code>Acme\\User\\Models\\UserSetting::class</code>.</td></tr><tr><td><strong>permissions</strong></td><td>массив разрешений, которые должен иметь пользователь панели управления для просмотра элемента меню (Примечание: прямой доступ по URL по-прежнему требует отдельных проверок разрешений), необязательно.</td></tr><tr><td><strong>context</strong></td><td>указывает размещение элемента настроек: <code>system</code> или <code>mysettings</code>. По умолчанию: <code>system</code>.</td></tr><tr><td><strong>size</strong></td><td>размер формы настроек при использовании с определением <code>class</code>. Поддерживаемые значения: <code>tiny</code>, <code>small</code>, <code>medium</code>, <code>large</code>, <code>huge</code>, <code>giant</code>, <code>adaptive</code>. По умолчанию: <code>large</code>.</td></tr></tbody></table></div><p>Для совместимости с другими плагинами доступны следующие общие константы для свойства <code>category</code>.</p>`,11)),n[2]||(n[2]=s("div",{class:"content-list",markdown:"1"},[s("ul",null,[s("li",null,"CATEGORY_CMS"),s("li",null,"CATEGORY_MISC"),s("li",null,"CATEGORY_MAIL"),s("li",null,"CATEGORY_LOGS"),s("li",null,"CATEGORY_SHOP"),s("li",null,"CATEGORY_TEAM"),s("li",null,"CATEGORY_USERS"),s("li",null,"CATEGORY_SOCIAL"),s("li",null,"CATEGORY_SYSTEM"),s("li",null,"CATEGORY_EVENTS"),s("li",null,"CATEGORY_BACKEND"),s("li",null,"CATEGORY_CUSTOMERS"),s("li",null,"CATEGORY_MYSETTINGS"),s("li",null,"CATEGORY_NOTIFICATIONS"),s("li",null,"CATEGORY_GLOBALS"),s("li",null,"CATEGORY_COLLECTIONS")])],-1)),n[3]||(n[3]=e(`<p>Необязательный параметр <code>keywords</code> используется функцией поиска настроек. Если ключевые слова не указаны, поиск использует только метку и описание элемента настроек.</p><h2 id="привязка-к-классу-модели"><a href="#привязка-к-классу-модели" class="header-anchor">#</a> Привязка к классу модели</h2><p>При привязке к <code>class</code> модели, указанному в свойствах настроек, вам не нужно создавать собственный контроллер, и это полезно для большинства случаев. Следующий пример создаёт ссылку на модель настроек, подробнее описанную в <a href="./model-settings.html">статье о настройках модели</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User Settings&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage user based settings.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;security location&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.users.access_settings&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Для формы используется универсальный контроллер панели управления с базовыми функциями, такими как сохранение и сброс значений по умолчанию. Активная навигация настраивается автоматически. Определённые разрешения также применяются контроллером.</p><h2 id="привязка-к-классу-контроллера"><a href="#привязка-к-классу-контроллера" class="header-anchor">#</a> Привязка к классу контроллера</h2><p>При указании <code>url</code> страницы в свойствах настроек вы можете создать собственный контроллер и связать его в области настроек. Следующий пример показывает, как создать ссылку на страницу панели управления.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;location&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Locations&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage available user countries and states.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-globe&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/user/locations&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;geography place placement&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="определение-класса-страницы-настроек"><a href="#определение-класса-страницы-настроек" class="header-anchor">#</a> Определение класса страницы настроек</h3><p>Контроллеры страниц настроек могут быть любыми <a href="./../system/controllers.html">контроллерами панели управления</a>, но для упрощения вы можете наследовать базовый класс <code>Backend\\Classes\\SettingsController</code>. Этот класс автоматически регистрирует контекст навигации настроек в контроллере. Вам нужно лишь указать код настроек в свойстве <code>$settingsItemCode</code>, используемом для определения активного элемента меню.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>SettingsController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsItemCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../system/controllers.html">Контроллеры панели управления</a></li></ul></div>`,13))])}const q=l(r,[["render",u]]);export{f as __pageData,q as default};
